 * Parses an election from the raw standard-input text: a `candidates` line
 * declaring the field followed by any number of `ballot` lines. Throws a
 * `CliError` describing the first problem found.
 */
export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  let candidateSet = null
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const lineNo = i + 1
    const tokens = line.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        throw new CliError(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 2) {
        throw new CliError(lineNo, 'expected candidates <name>...')
      }
      const names = tokens.slice(1)
      const set = new Set()
      for (const name of names) {
        if (!NAME_PATTERN.test(name)) {
          throw new CliError(lineNo, `invalid candidate name ${name}`)
        }
        if (set.has(name)) {
          throw new CliError(lineNo, `candidate ${name} is declared twice`)
        }
        set.add(name)
      }
      candidates = names
      candidateSet = set
    } else if (directive === 'ballot') {
      if (candidates === null) {
        throw new CliError(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        throw new CliError(lineNo, 'expected ballot <count> <candidate>...')
      }
      if (!COUNT_PATTERN.test(tokens[1])) {
        throw new CliError(lineNo, 'count must be a positive integer')
      }
      const count = BigInt(tokens[1])
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new CliError(lineNo, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          throw new CliError(lineNo, `candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      throw new CliError(lineNo, `unknown directive ${directive}`)
    }
  }

  if (candidates === null) {
    throw new CliError(null, 'no candidates')
  }

  return { candidates, ballots }
}
