 * Counts an election by instant-runoff rounds. Returns the list of rounds
 * counted and the winner's name, or `null` when nobody reaches a majority.
 *
 * Each round holds `counts` (a Map from continuing candidate name to their
 * vote total for that round, ordered by descending votes then ascending
 * name), `exhausted` (how many ballots counted for nobody), and
 * `eliminated` (the name removed after the round, or `null` for the final
 * round).
 */
export function runElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0n)
    let exhausted = 0n

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }

    let activeTotal = 0n
    for (const value of votes.values()) activeTotal += value

    history.push(votes)

    const ordered = [...continuing].sort((a, b) => {
      const diff = votes.get(b) - votes.get(a)
      if (diff > 0n) return 1
      if (diff < 0n) return -1
      return a < b ? -1 : a > b ? 1 : 0
    })

    let roundWinner = null
    for (const name of continuing) {
      if (votes.get(name) * 2n > activeTotal) {
        roundWinner = name
        break
      }
    }

    if (roundWinner !== null) {
      winner = roundWinner
      rounds.push({ counts: ordered.map((name) => [name, votes.get(name)]), exhausted, eliminated: null })
      break
    }

    if (activeTotal === 0n) {
      rounds.push({ counts: ordered.map((name) => [name, votes.get(name)]), exhausted, eliminated: null })
      break
    }

    const eliminated = pickEliminated(continuing, votes, history)
    rounds.push({ counts: ordered.map((name) => [name, votes.get(name)]), exhausted, eliminated })
    continuing = new Set([...continuing].filter((name) => name !== eliminated))
  }

  return { rounds, winner }
}

function pickEliminated(continuing, votes, history) {
  const min = [...continuing].reduce((m, name) => (votes.get(name) < m ? votes.get(name) : m), null)
  let tied = [...continuing].filter((name) => votes.get(name) === min)

  for (const roundVotes of history) {
    if (tied.length === 1) break
    const roundMin = tied.reduce((m, name) => {
      const v = roundVotes.get(name)
      return m === null || v < m ? v : m
    }, null)
    tied = tied.filter((name) => roundVotes.get(name) === roundMin)
  }

  return tied.reduce((last, name) => (name > last ? name : last))
}
"}

